<?php require_once __DIR__.'/includes/functions.php';if(current_user())redirect('dashboard.php');$error='';$email='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');$stmt=db()->prepare('SELECT id,password_hash FROM users WHERE email=?');$stmt->execute([$email]);$u=$stmt->fetch();if($u && password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=(int)$u['id'];redirect('dashboard.php');}$error='Invalid email or password.';}page_start('Sign in');?>
<section class="auth-wrap"><div class="hero"><span class="eyebrow">WELCOME BACK</span><h1>Everything you need, <em>one place.</em></h1><p>A beautiful and secure space to manage your account.</p><div class="glow"></div></div><div class="panel auth-panel"><h2>Sign in</h2><p class="muted">New here? <a href="<?=e(url('register.php'))?>">Create an account</a></p><?php if($error):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><label>Email address<input type="email" name="email" autocomplete="email" required value="<?=e($email)?>" placeholder="you@example.com"></label><label>Password<input type="password" name="password" autocomplete="current-password" required placeholder="Your password"></label><button class="button" type="submit">Sign in →</button></form></div></section><?php page_end(); ?>
